{"content":"# Нон-рут nginx: pid і тимчасові файли — в /tmp, бо /var/run і /var/cache/nginx не належать nginx (TZ §6).
worker_processes auto;
pid /tmp/nginx.pid;
error_log /tmp/nginx-error.log warn;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    access_log off;
    sendfile on;
    client_body_temp_path /tmp/nginx-client;
    proxy_temp_path /tmp/nginx-proxy;
    fastcgi_temp_path /tmp/nginx-fastcgi;
    uwsgi_temp_path /tmp/nginx-uwsgi;
    scgi_temp_path /tmp/nginx-scgi;
    include /etc/nginx/conf.d/*.conf;
}
","filePath":"/home/alex/v4_test/shop/qwen3.8-27b-iq4-xs/apps/web/nginx/nginx.conf"}

{"content":"server {
    listen 8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    # Безпека (TZ §5): CSP і захисні заголовки
    add_header Content-Security-Policy "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'none'" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header X-Frame-Options "DENY" always;

    # API проксі (TZ §6: nginx віддає статичну збірку й проксює /api → api)
    location /api/ {
        proxy_pass http://api:4000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # SPA: будь-який інший шлях — index.html
    location / {
        try_files $uri $uri/ /index.html;
    }
}
