{"content":"import Fastify, { type FastifyInstance } from "fastify";

export interface HealthReply {
  status: "ok";
  service: string;
  timestamp: string;
}

export function buildApp(): FastifyInstance {
  const app = Fastify({
    logger: true,
  });

  app.get<{ Reply: HealthReply }>("/api/health", async () => {
    return {
      status: "ok",
      service: "cybersphere-api",
      timestamp: new Date().toISOString(),
    };
  });

  return app;
}
